package com.wanyuecity.energy.stall.service;

import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;
import com.wanyuecity.energy.core.BizException;
import com.wanyuecity.energy.stall.entity.*;
import com.wanyuecity.energy.stall.mapper.*;
import com.wanyuecity.energy.stall.service.dto.*;
import lombok.RequiredArgsConstructor;
import org.springframework.beans.BeanUtils;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import com.wanyuecity.energy.system.mapper.CableSpecificationMapper;
import com.wanyuecity.energy.system.entity.CableSpecification;
import com.wanyuecity.energy.system.mapper.PowerSwitchSpecificationMapper;
import com.wanyuecity.energy.system.entity.PowerSwitchSpecification;
import com.wanyuecity.energy.system.service.BusinessDictionaryService;
import java.math.BigDecimal;
import java.util.*;
import java.util.stream.Collectors;

@Service @RequiredArgsConstructor
public class StallEngineeringService {
    private final StallMapper stallMapper; private final StallEngineeringProfileMapper mapper; private final StallEngineeringCableMapper cableMapper; private final CableSpecificationMapper specificationMapper; private final PowerSwitchSpecificationMapper switchSpecificationMapper; private final BusinessDictionaryService dictionaryService;
    public StallEngineeringView get(Long stallId){Stall stall=requireStall(stallId);StallEngineeringProfile profile=mapper.selectOne(new LambdaQueryWrapper<StallEngineeringProfile>().eq(StallEngineeringProfile::getStallId,stallId).last("LIMIT 1"));if(profile==null){profile=new StallEngineeringProfile();profile.setStallId(stallId);defaults(profile);}return view(stall,profile);}
    @Transactional public StallEngineeringView save(Long stallId,StallEngineeringRequest req){Stall stall=requireStall(stallId);validateConditional(req);validateCables(req.getCables());StallEngineeringProfile row=mapper.selectOne(new LambdaQueryWrapper<StallEngineeringProfile>().eq(StallEngineeringProfile::getStallId,stallId).last("LIMIT 1"));boolean create=row==null;if(create){row=new StallEngineeringProfile();row.setStallId(stallId);}BeanUtils.copyProperties(req,row);defaults(row);clearDisabled(row);if(create)mapper.insert(row);else mapper.updateById(row);replaceCables(row.getId(),req.getCables());syncLegacyCableFields(row,req.getCables());return view(stall,row);}
    private void validateCables(List<StallCableRequest> cables){if(cables==null)return;for(var item:cables){var spec=specificationMapper.selectById(item.getCableSpecificationId());if(spec==null)throw BizException.badRequest("所选电缆规格不存在");if(!Integer.valueOf(1).equals(spec.getStatus()))throw BizException.badRequest("电缆规格已停用："+spec.getCableModel()+" "+spec.getSpecification());if(item.getPowerSwitchSpecificationId()==null)throw BizException.badRequest("每套供配电回路必须选择供电端开关");var sw=switchSpecificationMapper.selectById(item.getPowerSwitchSpecificationId());if(sw==null||!Integer.valueOf(1).equals(sw.getStatus()))throw BizException.badRequest("所选供电端开关不存在或已停用");if(blank(item.getMeterLocationCode())||!dictionaryService.isEnabled("METER_LOCATION",item.getMeterLocationCode()))throw BizException.badRequest("每套供配电回路必须选择有效的电表位置");}}
    private void replaceCables(Long profileId,List<StallCableRequest> cables){if(cables==null)return;cableMapper.delete(new LambdaQueryWrapper<StallEngineeringCable>().eq(StallEngineeringCable::getStallEngineeringProfileId,profileId));for(var item:cables){var row=new StallEngineeringCable();row.setStallEngineeringProfileId(profileId);row.setCableSpecificationId(item.getCableSpecificationId());row.setPowerSwitchSpecificationId(item.getPowerSwitchSpecificationId());row.setQuantity(1);row.setSwitchQuantity(1);row.setMeterLocationCode(item.getMeterLocationCode());cableMapper.insert(row);}}
    private void syncLegacyCableFields(StallEngineeringProfile profile,List<StallCableRequest> cables){if(cables==null)return;profile.setCableQuantity(cables.size());profile.setCableModel(cables.stream().map(x->specificationMapper.selectById(x.getCableSpecificationId())).filter(Objects::nonNull).map(x->x.getCableModel()+" "+x.getSpecification()).collect(Collectors.joining("；")));mapper.updateById(profile);}
    private Stall requireStall(Long id){Stall s=stallMapper.selectById(id);if(s==null)throw BizException.notFound("铺位不存在");return s;}
    private void validateConditional(StallEngineeringRequest r){if(Boolean.TRUE.equals(r.getWaterSupply())&&blank(r.getWaterMeterCaliber()))throw BizException.badRequest("供水铺位必须填写水表口径");if(Boolean.TRUE.equals(r.getDrainageAvailable())&&blank(r.getDrainagePipeCaliber()))throw BizException.badRequest("有排水管时必须填写排水管口径");if(Boolean.TRUE.equals(r.getGasConnected())&&!Boolean.TRUE.equals(r.getGasConditionAvailable()))throw BizException.badRequest("已接通燃气时必须具备燃气条件");if(Boolean.TRUE.equals(r.getGasConnected())&&(blank(r.getGasType())||blank(r.getGasPipelineNo())))throw BizException.badRequest("已接通燃气时必须填写燃气类型和管道编号");if(Boolean.TRUE.equals(r.getGasAccepted())&&(r.getGasAcceptanceDate()==null||blank(r.getGasAcceptanceOrg())))throw BizException.badRequest("燃气已验收时必须填写验收日期和验收单位");}
    private void defaults(StallEngineeringProfile r){if(r.getCableQuantity()==null)r.setCableQuantity(0);if(r.getAirConditionerQuantity()==null)r.setAirConditionerQuantity(0);if(r.getFanCoilQuantity()==null)r.setFanCoilQuantity(0);if(r.getHangingCabinetQuantity()==null)r.setHangingCabinetQuantity(0);if(r.getAirOutletQuantity()==null)r.setAirOutletQuantity(0);if(r.getGasPipeQuantity()==null)r.setGasPipeQuantity(0);if(r.getGasAlarmQuantity()==null)r.setGasAlarmQuantity(0);if(r.getWaterSupply()==null)r.setWaterSupply(false);if(r.getDrainageAvailable()==null)r.setDrainageAvailable(false);if(r.getExhaustDuctAvailable()==null)r.setExhaustDuctAvailable(false);if(r.getFreshAirDuctAvailable()==null)r.setFreshAirDuctAvailable(false);if(r.getGasConditionAvailable()==null)r.setGasConditionAvailable(false);if(r.getGasConnected()==null)r.setGasConnected(false);if(r.getGasAlarm()==null)r.setGasAlarm(false);if(r.getAutoShutoffValve()==null)r.setAutoShutoffValve(false);if(r.getGasAccepted()==null)r.setGasAccepted(false);}
    private void clearDisabled(StallEngineeringProfile r){if(!r.getWaterSupply()){r.setWaterMeterCaliber(null);r.setWaterMeterLocation(null);}if(!r.getDrainageAvailable()){r.setDrainagePipeCaliber(null);r.setDrainagePipelineNo(null);}if(!r.getExhaustDuctAvailable())r.setExhaustDuctNo(null);if(!r.getFreshAirDuctAvailable())r.setFreshAirDuctNo(null);if(!r.getGasConditionAvailable()){r.setGasConnected(false);r.setGasType(null);r.setGasPipeQuantity(0);r.setGasPipeCaliber(null);r.setGasPipelineNo(null);r.setGasInterfaceLocation(null);r.setGasMeterNo(null);r.setGasMeterModel(null);r.setGasMeterLocation(null);r.setDesignGasFlow(null);r.setDesignGasLoadKw(null);r.setGasValveNo(null);r.setGasAlarm(false);r.setGasAlarmQuantity(0);r.setAutoShutoffValve(false);r.setGasAccepted(false);r.setGasAcceptanceDate(null);r.setGasAcceptanceOrg(null);}else if(!r.getGasConnected()){r.setGasMeterNo(null);r.setGasMeterModel(null);r.setGasMeterLocation(null);}if(!r.getGasAlarm())r.setGasAlarmQuantity(0);if(!r.getGasAccepted()){r.setGasAcceptanceDate(null);r.setGasAcceptanceOrg(null);}}
    private StallEngineeringView view(Stall s,StallEngineeringProfile p){StallEngineeringView v=new StallEngineeringView();v.setStallId(s.getId());v.setStallCode(s.getStallCode());v.setStallName(s.getStallName());v.setFloorCode(s.getFloorCode());v.setBusinessType(s.getBusinessType());v.setProfile(p);List<StallCableView> cables=p.getId()==null?List.of():cableMapper.selectList(new LambdaQueryWrapper<StallEngineeringCable>().eq(StallEngineeringCable::getStallEngineeringProfileId,p.getId())).stream().map(this::cableView).filter(Objects::nonNull).collect(Collectors.toList());v.setCables(cables);v.setTotalCableCurrentA(cables.stream().map(StallCableView::getTotalCurrentA).reduce(BigDecimal.ZERO,BigDecimal::add));v.setTotalCablePowerKw(cables.stream().map(StallCableView::getTotalPowerKw).reduce(BigDecimal.ZERO,BigDecimal::add));return v;}
    private StallCableView cableView(StallEngineeringCable link){CableSpecification spec=specificationMapper.selectById(link.getCableSpecificationId());if(spec==null)return null;var v=new StallCableView();v.setCableSpecificationId(spec.getId());v.setSpecCode(spec.getSpecCode());v.setCableModel(spec.getCableModel());v.setSpecification(spec.getSpecification());v.setRatedCurrentA(spec.getRatedCurrentA());v.setRatedPowerKw(spec.getRatedPowerKw());v.setQuantity(1);v.setTotalCurrentA(spec.getRatedCurrentA());v.setTotalPowerKw(spec.getRatedPowerKw());v.setSwitchQuantity(1);v.setMeterLocationCode(link.getMeterLocationCode());v.setMeterLocationName(dictionaryService.label("METER_LOCATION",link.getMeterLocationCode()));if(link.getPowerSwitchSpecificationId()!=null){PowerSwitchSpecification sw=switchSpecificationMapper.selectById(link.getPowerSwitchSpecificationId());if(sw!=null){v.setPowerSwitchSpecificationId(sw.getId());v.setSwitchSpecCode(sw.getSpecCode());v.setSwitchBrand(sw.getBrand());v.setSwitchModel(sw.getSwitchModel());v.setSwitchPoleCount(sw.getPoleCount());v.setSwitchRatedCurrentA(sw.getRatedCurrentA());v.setSwitchBreakingCapacityKa(sw.getBreakingCapacityKa());v.setSwitchType(sw.getSwitchType());v.setSwitchMatchStatus(sw.getRatedCurrentA().compareTo(spec.getRatedCurrentA())<=0?"匹配":"开关额定电流超过电缆载流量");}}return v;}private boolean blank(String v){return v==null||v.isBlank();}
}
